<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use RuntimeException;
class Wallet extends Model { use HasFactory; protected $fillable=['user_id','balance','reserved_balance','currency']; protected $casts=['balance'=>'decimal:2','reserved_balance'=>'decimal:2']; public function user(){return $this->belongsTo(User::class);} public function transactions(){return $this->hasMany(WalletTransaction::class);} public function activities(){return $this->hasMany(FinancialActivity::class);} public function getAvailableBalanceAttribute(): float{return max(0,(float)$this->balance-(float)$this->reserved_balance);} public function getFormattedBalanceAttribute(){return '$'.number_format((float)$this->balance,2);} public function getFormattedAvailableBalanceAttribute(){return '$'.number_format($this->available_balance,2);} public function getFormattedReservedBalanceAttribute(){return '$'.number_format((float)$this->reserved_balance,2);} public function canWithdraw($amount): bool{return $this->available_balance >= (float)$amount;} public function addFunds($amount){$this->increment('balance',$amount);return $this->refresh();} public function deductFunds($amount){if(!$this->canWithdraw($amount))throw new RuntimeException('Insufficient available balance');$this->decrement('balance',$amount);return $this->refresh();} public function reserveFunds($amount){if(!$this->canWithdraw($amount))throw new RuntimeException('Insufficient available balance');$this->increment('reserved_balance',$amount);return $this->refresh();} public function releaseReservedFunds($amount){if((float)$this->reserved_balance<(float)$amount)throw new RuntimeException('Reserved balance is lower than the requested release');$this->decrement('reserved_balance',$amount);return $this->refresh();} public function settleReservedDebit($amount){if((float)$this->reserved_balance<(float)$amount)throw new RuntimeException('Reserved balance is lower than the settlement amount');if((float)$this->balance<(float)$amount)throw new RuntimeException('Wallet balance is lower than the settlement amount');$this->decrement('reserved_balance',$amount);$this->decrement('balance',$amount);return $this->refresh();} public function getTotalDepositsAttribute(){return $this->transactions()->where('type','deposit')->where('status','completed')->sum('amount');} public function getTotalWithdrawalsAttribute(){return $this->transactions()->where('type','withdrawal')->where('status','completed')->sum('amount');} public function getTotalInvestmentsAttribute(){return $this->transactions()->where('type','investment')->where(function($q){$q->where('direction','debit')->orWhere(function($legacy){$legacy->whereNull('direction')->where(function($d){$d->whereNull('description')->orWhere('description','not like','Sale of%');});});})->where('status','completed')->sum('amount');} }
